#include <cstdio>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long s = 0, mn = 0, x;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &x);
        s += x;
        if (s < mn) mn = s;  // minimum prefix sum (empty prefix counts as 0)
    }
    printf("%lld\n", 1 - mn);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long s = 0, mn = 0;
        for (int i = 0; i < n; i++) {
            st.nextToken();
            s += (long) st.nval;
            mn = Math.min(mn, s); // minimum prefix sum (empty prefix counts as 0)
        }
        System.out.println(1 - mn);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n int
	fmt.Fscan(in, &n)
	var s, mn int64
	for i := 0; i < n; i++ {
		var x int64
		fmt.Fscan(in, &x)
		s += x
		mn = min(mn, s) // minimum prefix sum (empty prefix counts as 0)
	}
	fmt.Println(1 - mn)
}
